#include<bits/stdc++.h>
using namespace std;
int main(){
    int N;
    scanf("%d",&N);
    vector<int>par(N+1,0);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){
        scanf("%d",&par[i]);
        ch[par[i]].push_back(i);
    }
    vector<int>leaves;
    // DFS to get leaves in order
    function<void(int)> dfs=[&](int u){
        if(ch[u].empty()){leaves.push_back(u);return;}
        for(int c:ch[u]) dfs(c);
    };
    dfs(1);
    int L=leaves.size();
    if(N<=2){
        // trivial
        printf("1\n%d",N);
        for(int i=1;i<=N;i++)printf(" %d",i);
        printf("\n");
        return 0;
    }
    map<int,int>leafPos;
    for(int i=0;i<L;i++) leafPos[leaves[i]]=i;
    // For each internal node, find range of leaf indices [first_leaf, last_leaf]
    vector<int>fl(N+1,-1),ll(N+1,-1);
    function<void(int)> calc=[&](int u){
        if(ch[u].empty()){fl[u]=ll[u]=leafPos[u];return;}
        for(int c:ch[u]) calc(c);
        fl[u]=fl[ch[u][0]]; ll[u]=ll[ch[u].back()];
    };
    calc(1);
    vector<vector<int>>bags;
    vector<pair<int,int>>edges;
    // For each node, its "top" bag index (containing u and par[u])
    vector<int>top(N+1,-1),bot(N+1,-1);
    function<void(int)> build=[&](int u){
        if(ch[u].empty()){
            int nxt=leaves[(leafPos[u]+1)%L];
            vector<int>b={u,nxt};
            if(par[u])b.push_back(par[u]);
            sort(b.begin(),b.end());b.erase(unique(b.begin(),b.end()),b.end());
            top[u]=bot[u]=bags.size();bags.push_back(b);
            return;
        }
        for(int c:ch[u]) build(c);
        int prev=-1;
        for(int j=0;j<(int)ch[u].size();j++){
            int c=ch[u][j];
            int nxtLeaf=leaves[(ll[c]+1)%L];
            vector<int>b={u,c,nxtLeaf};
            if(par[u])b.push_back(par[u]);
            sort(b.begin(),b.end());b.erase(unique(b.begin(),b.end()),b.end());
            int id=bags.size();bags.push_back(b);
            if(j==0)top[u]=id;
            if(j==(int)ch[u].size()-1)bot[u]=id;
            edges.push_back({id,bot[c]});
            if(prev>=0)edges.push_back({prev,id});
            prev=id;
        }
    };
    build(1);
    printf("%d\n",(int)bags.size());
    for(auto&b:bags){printf("%d",(int)b.size());for(int x:b)printf(" %d",x);printf("\n");}
    for(auto&[a,b]:edges)printf("%d %d\n",a+1,b+1);
}
